package com.bananalab.lite;
import android.content.Context;import org.json.*;import java.util.*;import java.util.regex.*;
/** Quote-aware 12-step scene transactions and editable, persistent plans. */
final class MobilePlan{
 static final int MAX=12;
 static List<String> split(String input){String text=input.replace('“','"').replace('”','"');StringBuilder marked=new StringBuilder();boolean quoted=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'&&(i==0||text.charAt(i-1)!='\\'))quoted=!quoted;if(!quoted&&(c==';'||c=='\n'))marked.append("\u0001");else marked.append(c);}String[] spans=marked.toString().split("\u0001",-1);List<String> rows=new ArrayList<>();for(String span:spans){StringBuilder out=new StringBuilder();quoted=false;for(int i=0;i<span.length();){char c=span.charAt(i);if(c=='"'&&(i==0||span.charAt(i-1)!='\\')){quoted=!quoted;out.append(c);i++;continue;}if(!quoted){Matcher m=Pattern.compile("(?iu)^(?:,?\\s+(?:y\\s+)?(?:despu[eé]s|luego|por [uú]ltimo)(?!\\s+de\\b)\\s+)").matcher(span.substring(i));if(m.find()){out.append('\u0001');i+=m.end();continue;}}out.append(c);i++;}for(String raw:out.toString().split("\u0001")){String s=raw.replaceFirst("(?iu)^\\s*(?:[-•]|[0-9]{1,2}[.)])?\\s*(?:primero[:,]?\\s+|despu[eé]s\\s+|luego\\s+)?","").trim();if(!s.isEmpty())rows.add(s);}}return rows;}
 static String snapshot(Context c)throws Exception{CreatorSession owner=CreatorMemory.load(c);SceneDraft actual=SceneStore.load(c);return owner.json()+"\n"+(actual==null?"":actual.json().toString())+"\nmodules:"+RuntimeModules.revision(c);}
 static String describe(List<String> rows){StringBuilder b=new StringBuilder("Plan de "+rows.size()+" pasos:");for(int i=0;i<rows.size();i++)b.append("\n").append(i+1).append(". ").append(rows.get(i));return b.toString();}
 static String canonical(String input,SceneDraft scene){if(ChatLanguage.normalize(input).contains(" dice "))return input;String q=CreationRequest.normalize(input).replaceFirst("^(?:y |que )","");q=MobileCore.rewrite(q);if(scene!=null&&ScenePlanner.VERB.matcher(q).find()&&!q.matches("(?s)^(?:crea|creame|dibuja|dibujame|quiero|haceme|continua|segui|sigue|agrega|pone|cambia|reemplaza|reinicia|hace que dure|quita).*" )&&!q.contains(" dice "))q="continua con "+q;return q;}
 static BananaEngine.Result apply(Context c,Semilla model,List<String> rows)throws Exception{if(rows.size()<1||rows.size()>MAX)return MobileCore.say(c,"Dividí el pedido en entre uno y doce pasos.","plan");CreatorSession owner=CreatorMemory.load(c);SceneDraft actual=SceneStore.load(c),base=owner.pending!=null?owner.pending:actual;CreatorSession sandbox=CreatorSession.read(owner.json());sandbox.composing=true;sandbox.pending=null;SceneDraft current=base==null?null:base.copy();List<String> applied=new ArrayList<>();String start=snapshot(c);RuntimeProgram modules=new RuntimeProgram(RuntimeModules.code(c));
  for(int i=0;i<rows.size();i++){String step=canonical(rows.get(i),current),q=ChatLanguage.normalize(step);if(q.matches("(?s).*(?:borrador|deshacer|rehacer|recuerdo|recorda|internet|referencia|siguiente toma|nueva serie|recupera serie|aplica el plan|exporta).*"))return fail(c,rows,start,i,"Ese paso necesita ejecutarse por separado.");RuntimeProgram.Result dynamic=modules.run(rows.get(i),current);CreatorSession.Result r=dynamic.matched?(dynamic.scene==null?CreatorSession.say(dynamic.error):new CreatorSession.Result(true,"Comportamiento local "+dynamic.module,dynamic.scene)):sandbox.apply(model,step,current);if(!r.handled||r.commit==null||r.importReference)return fail(c,rows,start,i,r.handled?r.text:"No identifiqué una operación de escena completa.");String problem=BananaPixel.limitation(r.commit);if(problem==null)problem=SceneConsistency.problem(r.commit);if(problem!=null)return fail(c,rows,start,i,problem);current=SceneDraft.read(r.commit.json().toString());applied.add(step);}
  if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Plan cancelado");if(!snapshot(c).equals(start))return MobileCore.say(c,"El proyecto cambió durante el pedido. Conservé la versión actual; prepará el plan otra vez.","plan");String receipt=TaskReceipt.describe(base,current,applied.toArray(new String[0]));owner.lastTask=receipt;CreatorSession.Result result=owner.update(current,owner.pending!=null,receipt,false);CreatorMemory.save(c,owner,result.commit);MobileCore.prefs(c).edit().remove("plan").remove("planSnapshot").remove("failedStep").apply();BananaEngine.Result out=MobileCore.say(c,receipt,"plan");out.changed=result.commit!=null;if(out.draft)out.mode="borrador";return out;}
 static BananaEngine.Result fail(Context c,List<String> rows,String start,int i,String why)throws Exception{save(c,rows,start);MobileCore.prefs(c).edit().putInt("failedStep",i+1).apply();return MobileCore.say(c,"No apliqué ninguno de los pasos. Paso "+(i+1)+": "+rows.get(i)+"\n"+why+"\nPodés decir ‘corrige paso "+(i+1)+": …’ y después ‘aplica el plan’. La escena anterior se conserva.","plan");}
 static void save(Context c,List<String> rows,String snapshot)throws Exception{if(rows.isEmpty()||rows.size()>MAX)throw new java.io.IOException("El plan admite de uno a doce pasos.");if(!MobileCore.prefs(c).edit().putString("plan",new JSONArray(rows).toString()).putString("planSnapshot",snapshot).commit())throw new java.io.IOException("No pude guardar el plan.");}
 static List<String> stored(Context c)throws Exception{JSONArray a=new JSONArray(MobileCore.prefs(c).getString("plan","[]"));List<String> rows=new ArrayList<>();if(a.length()>MAX)throw new java.io.IOException("Plan inválido");for(int i=0;i<a.length();i++)rows.add(a.getString(i));return rows;}
}
